import type { StructuredLogger } from '../logging/structured-logger';
import type OpenAI from 'openai';
import type { ActionEntry, ToolArgs } from './unified-agent.types';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import { forEachSequential } from '../common/async-sequence';
import { isAllowedTool, parseToolArgs } from './unified-agent-tool-parser.helpers';
import { executeToolAction, type ExecuteToolActionDeps } from './unified-agent-tool-router.helpers';

type UnknownRecord = Record<string, unknown>;

export interface ProcessToolCallsDeps extends ExecuteToolActionDeps {
  actions: UnifiedAgentActionsService;
}

export async function processUnifiedAgentToolCalls(
  deps: ProcessToolCallsDeps,
  params: {
    workspaceId: string;
    contactId: string;
    phone: string;
    allowedTools?: string[];
    context?: UnknownRecord;
    assistantMessage: OpenAI.Chat.Completions.ChatCompletionMessage;
    logger: StructuredLogger;
  },
): Promise<ActionEntry[]> {
  const { workspaceId, contactId, phone, context, assistantMessage, logger } = params;
  const actionsList: ActionEntry[] = [];
  const toolCalls = assistantMessage.tool_calls;

  if (!toolCalls || toolCalls.length === 0) {
    return actionsList;
  }

  await forEachSequential(toolCalls, async (toolCall) => {
    if (toolCall.type !== 'function') {
      return;
    }
    const toolName = toolCall.function.name;
    if (!isAllowedTool(toolName, params.allowedTools)) {
      logger.warn(
        `Blocked disallowed agent tool call: workspaceId=${workspaceId} tool=${toolName}`,
      );
      const blockedResult = { blocked: true, reason: 'capability_not_allowed' };
      actionsList.push({ tool: toolName, args: {}, result: blockedResult });
      await deps.actions.logAutopilotEvent(workspaceId, contactId, toolName, {} as ToolArgs, blockedResult);
      return;
    }
    const toolArgs = parseToolArgs(toolCall.function.arguments, toolName, logger);
    const result = await executeToolAction(
      deps,
      workspaceId,
      contactId,
      phone,
      toolName,
      toolArgs,
      context,
    );
    actionsList.push({ tool: toolName, args: toolArgs, result });
    await deps.actions.logAutopilotEvent(workspaceId, contactId, toolName, toolArgs, result);
  });

  return actionsList;
}

import type { StructuredLogger } from '../logging/structured-logger';
import type OpenAI from 'openai';
import type {
  ActionEntry,
  PredecidedAction,
  ToolArgs,
} from './unified-agent.types';
import type { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import {
  buildPredecidedActionDraft,
  executePredecidedAgentActions,
} from './unified-agent-predecided-actions.part';
import { executeToolAction, type ExecuteToolActionDeps } from './unified-agent-tool-router.helpers';
import { recordAgentRuntimeTurn } from './unified-agent-runtime.helpers';
import type { AgentRuntimeContextService } from './agent-runtime/agent-runtime.context';
import { actionSucceeded } from './unified-agent-tool-router.helpers';

type UnknownRecord = Record<string, unknown>;

export interface ProcessPredecidedDeps extends ExecuteToolActionDeps {
  actions: UnifiedAgentActionsService;
  response: UnifiedAgentResponseService;
  agentRuntime?: AgentRuntimeContextService;
}

export async function processUnifiedAgentPredecidedActions(
  deps: ProcessPredecidedDeps,
  params: {
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
    allowedTools?: string[];
    predecidedActions: PredecidedAction[];
    conversationHistoryLength: number;
    channel: string;
  },
): Promise<{
  actions: ActionEntry[];
  response?: string;
  intent: string;
  confidence: number;
}> {
  const {
    workspaceId,
    contactId,
    phone,
    message,
    allowedTools,
    predecidedActions,
    conversationHistoryLength,
    channel,
  } = params;

  const actionsList = await executePredecidedAgentActions({
    ...(allowedTools !== undefined ? { allowedTools } : {}),
    contactId,
    ...(params.context !== undefined ? { context: params.context } : {}),
    executeTool: (wsId, ctId, ph, tool, args, ctx) =>
      executeToolAction(deps, wsId, ctId, ph, tool, args, ctx),
    logAutopilotEvent: deps.actions.logAutopilotEvent.bind(deps.actions),
    phone,
    predecidedActions,
    workspaceId,
  });

  const intent = deps.response.extractIntent(actionsList, message);
  const draftedReply = await deps.response.composeWriterReply(
    deps.openai,
    deps.writerModel ?? deps.primaryBrainModel,
    deps.fallbackBrainModel,
    {
      workspaceId,
      customerMessage: message,
      assistantDraft: buildPredecidedActionDraft(actionsList),
      actions: actionsList,
      historyTurns: conversationHistoryLength,
    },
  );

  await recordAgentRuntimeTurn(
    {
      workspaceId,
      channel,
      userMessage: message,
      ...(draftedReply !== undefined ? { assistantMessage: draftedReply } : {}),
      contactId,
      intent,
      confidence: actionsList.length > 0 ? 0.85 : 0.55,
      actions: actionsList.map((action) => ({
        toolName: action.tool,
        success: actionSucceeded(action.result),
        result: action.result,
      })),
    },
    deps.agentRuntime,
  );

  return {
    actions: actionsList,
    ...(draftedReply !== undefined ? { response: draftedReply } : {}),
    intent,
    confidence: actionsList.length > 0 ? 0.85 : 0.55,
  };
}

import type { StructuredLogger } from '../logging/structured-logger';
import type OpenAI from 'openai';
import type { ChatCompletionMessageParam } from 'openai/resources/chat';
import type { PrismaService } from '../prisma/prisma.service';
import type { PlanLimitsService } from '../billing/plan-limits.service';
import type { UnifiedAgentContextService } from './unified-agent-context.service';
import type { UnifiedAgentResponseService } from './unified-agent-response.service';
import type { AbiBuilderService } from './abi/abi-builder.service';
import { chatCompletionWithFallback } from './openai-wrapper';
import { formatPromptValue } from './unified-agent-tool-parser.helpers';
import { buildUnifiedAgentCognitiveState } from './unified-agent-cognitive-state.helpers';
import { buildAgentRuntimeContext } from './unified-agent-runtime.helpers';
import type { AgentRuntimeContextService } from './agent-runtime/agent-runtime.context';

type UnknownRecord = Record<string, unknown>;

const UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED =
  'Primary LLM configuration is required for unified agent generation';

export interface ProcessIncomingDeps {
  logger: StructuredLogger;
  prisma: PrismaService;
  ctx: UnifiedAgentContextService;
  response: UnifiedAgentResponseService;
  planLimits: PlanLimitsService;
  abiBuilder?: AbiBuilderService;
  agentRuntime?: AgentRuntimeContextService;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
}

export interface ProcessIncomingResult {
  messages: ChatCompletionMessageParam[];
  assistantMessage: OpenAI.Chat.Completions.ChatCompletionMessage;
  conversationHistory: ChatCompletionMessageParam[];
  contactName: string;
  contactSentiment: string;
  leadScore: string;
  tagNames: string;
  stylePolicy: string;
}

export async function processIncomingUnifiedAgentMessage(
  deps: ProcessIncomingDeps,
  params: {
    workspaceId: string;
    contactId: string;
    phone: string;
    message: string;
    context?: UnknownRecord;
    allowedTools?: string[];
  },
): Promise<ProcessIncomingResult> {
  const { workspaceId, contactId, phone, message, context } = params;

  const [workspace, contact, conversationHistory, products] = await Promise.all([
    deps.ctx.getWorkspaceContext(workspaceId),
    deps.ctx.getContactContext(workspaceId, contactId, phone),
    deps.ctx.getConversationHistory(workspaceId, contactId, 0, phone),
    deps.ctx.getProducts(workspaceId),
  ]);

  const productIds = products
    .map((product: UnknownRecord) => {
      const productValue = deps.ctx.readRecord(product.value);
      return deps.ctx.readOptionalText(productValue.id) || deps.ctx.readOptionalText(product.id);
    })
    .filter((productId): productId is string => Boolean(productId));
  let aiConfigs: UnknownRecord[] = [];
  if (productIds.length > 0) {
    try {
      aiConfigs = await deps.prisma.productAIConfig.findMany({
        take: 50,
        where: { productId: { in: productIds } },
        select: {
          id: true,
          productId: true,
          tone: true,
          persistenceLevel: true,
          messageLimit: true,
          customerProfile: true,
          positioning: true,
          objections: true,
          salesArguments: true,
        },
      });
    } catch {
      /* ProductAIConfig may not exist yet */
    }
  }

  const compressedContext = await deps.ctx.buildAndPersistCompressedContext(
    workspaceId,
    contactId,
    phone,
    contact,
  );
  const tacticalHint = deps.ctx.buildLeadTacticalHint({
    leadName: deps.ctx.isRecord(contact) ? deps.ctx.readText(contact.name).trim() : '',
    currentMessage: message,
    conversationHistory,
  });

  const agentRuntimeContext = await buildAgentRuntimeContext(
    {
      workspaceId,
      channel: deps.ctx.readText(context?.channel, 'whatsapp'),
      message,
      contactId,
      ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
    },
    deps.agentRuntime,
  );
  const systemPrompt = [
    deps.ctx.buildSystemPrompt(workspace, products, aiConfigs),
    agentRuntimeContext.systemPromptBlock,
  ].join('\n\n');
  const stylePolicy = deps.response.buildReplyStyleInstruction(
    message,
    conversationHistory.length,
  );
  const contactData: Record<string, unknown> = deps.ctx.isRecord(contact) ? contact : {};
  const contactName = deps.ctx.readText(contactData.name).trim() || phone;
  const contactSentiment = deps.ctx.readText(contactData.sentiment).trim() || 'NEUTRAL';
  const leadScore = deps.ctx.readText(contactData.leadScore, '0');
  const tagNames = deps.ctx.readTagList(contactData.tags);

  const additionalContext = context ? formatPromptValue(context) : '';
  const currentInput = {
    raw: message,
    channel: deps.ctx.readText(context?.channel, 'whatsapp'),
    arrivalTimestamp: new Date().toISOString(),
  };

  const cognitiveState = await buildUnifiedAgentCognitiveState({
    abiBuilder: deps.abiBuilder,
    logger: deps.logger,
    currentInput,
  });

  const messages: ChatCompletionMessageParam[] = [
    ...conversationHistory,
    {
      role: 'user',
      content: JSON.stringify({
        cognitiveState,
        runtimeContext: {
          workspaceProductContext: systemPrompt,
          compressedMemory: compressedContext || null,
          additionalContext,
          tacticalHint:
            tacticalHint || 'responder com clareza, valor concreto e próximo passo.',
          responsePolicy: stylePolicy,
        },
        contact: {
          name: contactName,
          sentiment: contactSentiment,
          leadScore,
          tags: tagNames,
        },
        currentInput,
      }),
    },
  ];

  const openai = deps.openai;
  if (!openai) {
    const error = new Error();
    error.message = UNIFIED_AGENT_PROVIDER_CONFIG_REQUIRED;
    throw error;
  }

  await deps.planLimits.ensureTokenBudget(params.workspaceId);

  const llmResponse = await chatCompletionWithFallback(
    openai,
    {
      model: deps.primaryBrainModel,
      messages,
      temperature: 0.82,
      top_p: 0.9,
    },
    deps.fallbackBrainModel,
  );

  const firstChoice = llmResponse.choices[0];
  if (!firstChoice) {
    throw new Error('LLM returned empty choices');
  }

  const assistantMessage = firstChoice.message;

  return {
    messages,
    assistantMessage,
    conversationHistory,
    contactName,
    contactSentiment,
    leadScore,
    tagNames,
    stylePolicy,
  };
}

